function ActivityOpenGridBigRewardListCell:RefreshUI()
    self.ImgBgFill.gameObject:SetActive(not self._data.isLast)
    self.ImgFill.fillAmount = self._data.fill
    self.TxtTitle.text = localize("_num_层", { _num_ = self._data.floor })
    ---@type GoodNodeMB
    local scr = CfUtils.GetLuaScr(self.GoodNode, "Game.Behaviours.GoodNodeMB")
    if scr then
        scr:Reload({
            goodsId = self._data.reward.goodsId,
            text = string.format("x%d", self._data.reward.num),
            isShowNo = true;
        })
        scr:SetClickCallback(function()
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self._data.reward.goodsId)
            if isTable(vo) then
                GameUtils.ShowCommonTipsBoard(self.controller.gameObject, vo.name, vo.desc, vo.quality, vo.id)
            end
        end)
        scr:SetSanXingGainShow(self._data.status == 1)
    end
end

